// Generates src/styles/tokens.css from design/tokens/figma-tokens.json.
// tokens.css is the only file allowed to contain raw colour and size values.
import { readFileSync, writeFileSync } from 'node:fs';

const root = new URL('..', import.meta.url);
const src = JSON.parse(readFileSync(new URL('design/tokens/figma-tokens.json', root), 'utf8'));
const rem = (px) => `${+(px / 16).toFixed(4)}rem`;
const lines = [];
const out = (s = '') => lines.push(s);

out(
  '/* GENERATED by scripts/generate-tokens.mjs from design/tokens/figma-tokens.json. Do not edit by hand. */',
);
out();
out(
  '/* Mode-aware values. The theme script sets data-theme="light" | "dark" on <html> before first paint. */',
);
out(':root {');
out('  color-scheme: light;');
for (const [name, v] of Object.entries(src.color)) out(`  --myds-${name}: ${v.light};`);
out('}');
out();
out(":root[data-theme='dark'] {");
out('  color-scheme: dark;');
for (const [name, v] of Object.entries(src.color))
  if (v.dark !== v.light) out(`  --myds-${name}: ${v.dark};`);
out('}');
out();
out('/* Tailwind theme: defaults are cleared so only Figma tokens exist. */');
out('@theme inline {');
out('  --color-*: initial;');
out('  --color-transparent: transparent;');
out('  --color-current: currentColor;');
for (const name of Object.keys(src.color)) out(`  --color-${name}: var(--myds-${name});`);
out('}');
out();
out('@theme {');
out('  --font-*: initial;');
for (const [k, v] of Object.entries(src.font)) out(`  --font-${k}: ${v};`);
out('  --text-*: initial;');
out('  --radius-*: initial;');
for (const [k, v] of Object.entries(src.radius))
  out(`  --radius-${k}: ${k === 'full' ? '9999px' : rem(v)};`);
out('  --shadow-*: initial;');
for (const [k, v] of Object.entries(src.shadow)) out(`  --shadow-${k}: ${v};`);
out('  --blur-*: initial;');
for (const [k, v] of Object.entries(src.blur)) out(`  --blur-${k}: ${v}px;`);
for (const [k, v] of Object.entries(src.gradient)) out(`  --background-image-${k}: ${v};`);
out('  --container-*: initial;');
for (const [k, v] of Object.entries(src.layout)) {
  if (k.startsWith('header')) out(`  --spacing-${k}: ${rem(v)};`);
  else out(`  --container-${k}: ${rem(v)};`);
}
out('}');
out();
out('/* Gradients as utilities: bg-hero-scrim, bg-nav-scrim */');
for (const k of Object.keys(src.gradient))
  out(`@utility bg-${k} {\n  background-image: var(--background-image-${k});\n}`);
out();
out(
  '/* Figma text styles. Use type-<style>; responsive steps like `type-heading-s lg:type-heading-l`. */',
);
for (const [k, t] of Object.entries(src.type)) {
  out(`@utility type-${k} {`);
  out(`  font-family: var(--font-${t.family});`);
  out(`  font-size: ${rem(t.size)};`);
  out(`  line-height: ${rem(t.line)};`);
  out(`  letter-spacing: ${t.tracking ? rem(t.tracking) : '0'};`);
  out(`  font-weight: ${t.weight};`);
  out('}');
}
writeFileSync(new URL('src/styles/tokens.css', root), lines.join('\n') + '\n');
console.log(
  `tokens: ${Object.keys(src.color).length} colours, ${Object.keys(src.type).length} text styles -> src/styles/tokens.css`,
);
